#!/usr/bin/env ruby
# Write a host header that embeds the macros the way an external generator does (e.g. fff's
# fakegen.rb): the host's own macros work without __VA_OPT__, and the embedded macros are in
# `#if PP_HAS_VA_OPT ... #endif` after the probe. Used by the embed_* tests in CMakeLists.txt.
#
# Usage: ruby test/embed_host.rb <output file>

require_relative '../pp_iterators'

abort "Usage: #{$0} <output file>" unless ARGV.size == 1

ppi = PPIterators.new(nargs_max: PPIterators::MAX_ARG_COUNT_DEFAULT)
File.write(ARGV[0], <<~EOH)
  // Generated by test/embed_host.rb. Do not edit.
  #ifndef EMBED_HOST_H
  #define EMBED_HOST_H

  // The host's own macros, which do not need __VA_OPT__
  #define HOST_CORE_VALUE 42

  #{ppi.va_opt_probe}
  #if PP_HAS_VA_OPT
  #{ppi.embed_macros(require_va_opt: false)}
  #endif // PP_HAS_VA_OPT

  #endif // EMBED_HOST_H
EOH
